/** The text of each kind of notice; {name} and the other placeholders are filled in when it is sent. */
export const TEMPLATES = {
  holdReady: {
    subject: 'Your hold is ready',
    body: 'Hello {name}, "{title}" is waiting for you at {branch}. Please collect it by {deadline}.',
  },
  dueSoon: {
    subject: 'An item is due soon',
    body: 'Hello {name}, "{title}" is due back on {dueOn}. You can renew it online.',
  },
  overdue: {
    subject: 'An item is overdue',
    body: 'Hello {name}, "{title}" was due back on {dueOn}. Please return it to any branch.',
  },
};
import { fillTemplate } from '../helpers/text.js';
import { displayName } from '../members/accounts.js';
import { addressFor, channelFor } from './channels.js';
import { TEMPLATES } from './templates.js';

/**
 * Builds a notice of one kind for a member: { channel, to, subject, body }. The subject is null
 * for a text message, which has none.
 */
export function composeNotice(kind, { member, values }) {
  const template = TEMPLATES[kind];
  if (template === undefined) throw new Error(`Unknown notice kind ${kind}`);
  const channel = channelFor(member);
  return {
    channel,
    to: addressFor(member, channel),
    subject: channel === 'email' ? template.subject : null,
    body: fillTemplate(template.body, { name: displayName(member), ...values }),
  };
}
// Days are calendar dates written as YYYY-MM-DD, read as UTC so that the server's time zone never
// shifts them.
const DAY_MS = 86_400_000;

function toTime(isoDate) {
  return Date.parse(`${isoDate}T00:00:00Z`);
}

/** Returns the calendar date `days` days after `isoDate`, or before it when `days` is negative. */
export function addDays(isoDate, days) {
  return new Date(toTime(isoDate) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Returns how many days `later` is after `earlier`, negative when it is before. */
export function daysBetween(earlier, later) {
  return Math.round((toTime(later) - toTime(earlier)) / DAY_MS);
}

/** Returns the day of the week of a calendar date, 0 for Sunday to 6 for Saturday. */
export function weekdayOf(isoDate) {
  return new Date(toTime(isoDate)).getUTCDay();
}

/** Tells whether a branch is open on a calendar date. */
export function isOpenOn(branch, isoDate) {
  return !branch.closedWeekdays.includes(weekdayOf(isoDate));
}

/** Returns the first date on or after `isoDate` on which the branch is open. */
export function nextOpenDay(branch, isoDate) {
  let day = isoDate;
  while (!isOpenOn(branch, day)) day = addDays(day, 1);
  return day;
}
/** Returns the loans not returned whose due date is before `today`, the longest overdue first. */
export function listOverdueLoans(store, today) {
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn < today)
    .sort((first, second) => first.dueOn.localeCompare(second.dueOn));
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { composeNotice } from '../lib/notices/compose.js';
import { dueSoonNotices, overdueNotices } from '../lib/notices/digest.js';
import { ADA, BEN, BOOK, DVD, sampleLoan, sampleStore, TODAY } from './sample-library.js';

test('a notice by email goes to the email address, with a subject', () => {
  const notice = composeNotice('dueSoon', {
    member: ADA,
    values: { title: BOOK.title, dueOn: '2026-11-27' },
  });
  assert.equal(notice.channel, 'email');
  assert.equal(notice.to, ADA.email);
  assert.equal(notice.subject, 'An item is due soon');
  assert.match(notice.body, /^Hello Ada Okafor, "The Left Hand of Darkness" is due back on 2026-11-27\./);
});

test('a notice by text message goes to the phone number, greets by the preferred name and has no subject', () => {
  const notice = composeNotice('dueSoon', { member: BEN, values: { title: DVD.title, dueOn: '2026-11-27' } });
  assert.equal(notice.channel, 'sms');
  assert.equal(notice.to, BEN.phone);
  assert.equal(notice.subject, null);
  assert.match(notice.body, /^Hello Ben,/);
});

test('the morning run reminds members of loans due within two days, and of overdue loans', () => {
  const store = sampleStore({
    loans: [
      sampleLoan({ id: 'loan_1', item: BOOK, member: ADA, checkedOutOn: '2026-11-07', dueOn: '2026-11-28' }),
      sampleLoan({ id: 'loan_2', item: DVD, member: BEN, checkedOutOn: '2026-11-12', dueOn: '2026-11-19' }),
    ],
  });
  assert.deepEqual(
    dueSoonNotices(store, TODAY).map((notice) => notice.to),
    [ADA.email],
  );
  assert.deepEqual(
    overdueNotices(store, TODAY).map((notice) => notice.to),
    [BEN.phone],
  );
});
